integrations.replacement:
// Driver app (home SDK contribution): the courier shell has no guest
// surface — every screen needs a signed-in courier account — so the
// login page's default-on guest Skip affordance is hidden here.
AuthEntryConfig.showsGuestSkip = false;

boot_hooks.body:
if (!kIsWeb && (defaultTargetPlatform == TargetPlatform.android || defaultTargetPlatform == TargetPlatform.iOS)) {
  try {
    await Workmanager().initialize(callbackDispatcher);
  } catch (e) {
    debugPrint('Workmanager boot skipped: $e');
  }
}

registration_steps.body:
RegistrationStep(
  data: const {'id': 'delivery.vehicle_details'},
  content: Builder(
    builder: (context) => VehicleDetailsSlide(
      capture: CourierVehicleDetailsAdapter(),
      onContinue: () => RegistrationStepScope.of(context).next(),
    ),
  ),
)
